const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  const t = (key: string): string => {
    const lang = systemStore.settings.language || 'en';
    const keys = key.split('.');
    let value: any = (translations as any)[lang];
    for (const k of keys) { value = value?.[k]; }
    return value || key;
  };

  const formatPrice = (amount: number) => {
    const symbol = systemStore.settings.currencySymbol;
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: symbol === '₭' ? 'LAK' : symbol === '฿' ? 'THB' : 'USD',
      minimumFractionDigits: symbol === '₭' ? 0 : 2,
    }).format(amount).replace('LAK', '₭').replace('THB', '฿');
  };

  const refreshData = async () => {
    console.debug("[Local Mode] Data refresh requested");
  };

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash', 
    amountReceived?: number, 
    change?: number, 
    pointsRedeemed?: number
  ): Promise<Sale> => {
    const saleId = `S-${Date.now()}`;
    const customer = salesStore.customers.find(c => c.id === customerId);

    const newSale: Sale = {
      id: saleId,
      items,
      total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      date: new Date().toISOString(),
      paymentMethod,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      amountReceived,
      change,
      remainingAmount: paymentMethod === 'credit' ? total : 0,
      status: 'completed',
      syncStatus: 'synced',
      customerId,
      customerName: customer?.name,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name
    };

    salesStore.addSale(newSale);

    items.forEach(item => {
       inventoryStore.updateProductStock(item.id, -item.quantity, 'wh1');
    });

    if (customerId && systemStore.settings.loyaltyProgram.enabled) {
       const earned = Math.floor(total / systemStore.settings.loyaltyProgram.earnRate);
       const updatedCustomer = { ...customer!, loyaltyPoints: (customer?.loyaltyPoints || 0) + earned - (pointsRedeemed || 0) };
       salesStore.updateCustomer(updatedCustomer as Customer);
    }

    return newSale;
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
    const sale = salesStore.sales.find(s => s.id === saleId);
    if (!sale) return;

    const newAmountReceived = (sale.amountReceived || 0) + amount;
    const newRemaining = Math.max(0, (sale.remainingAmount || sale.total) - amount);

    salesStore.updateSale({
      ...sale,
      amountReceived: newAmountReceived,
      remainingAmount: newRemaining,
      paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
    });

    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'CASH_IN',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Settled debt for Sale ${saleId}: ${amount}`,
       timestamp: new Date().toISOString(),
       severity: 'low',
       resourceId: saleId
    });
  };

  const processReturn = async (originalSale: Sale, returnItems: { itemIndex: number, quantity: number }[]) => {
    const returnSaleId = `RET-${Date.now()}`;
    const items: CartItem[] = [];
    let returnTotal = 0;

    returnItems.forEach(ret => {
       const originalItem = originalSale.items[ret.itemIndex];
       const returnQty = ret.quantity;
       const lineTotal = originalItem.sellPrice * returnQty;

       returnTotal += lineTotal;
       items.push({ ...originalItem, quantity: returnQty });

       inventoryStore.updateProductStock(originalItem.id, returnQty, 'wh1');
    });

    const returnSale: Sale = {
      id: returnSaleId,
      items,
      total: -returnTotal,
      date: new Date().toISOString(),
      paymentMethod: originalSale.paymentMethod,
      paymentStatus: 'paid',
      status: 'completed',
      type: 'return',
      originalSaleId: originalSale.id,
      customerId: originalSale.customerId,
      customerName: originalSale.customerName,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name
    };

    salesStore.addSale(returnSale);

    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'SALE_RETURN',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Processed return for Sale ${originalSale.id}`,
       timestamp: new Date().toISOString(),
       severity: 'medium',
       resourceId: originalSale.id
    });
  };

  const handleVoidSale = (id: string) => {
    const sale = salesStore.sales.find(s => s.id === id);
    if (!sale || sale.status === 'voided') return;

    salesStore.updateSale({ ...sale, status: 'voided' });

    sale.items.forEach(item => {
       inventoryStore.updateProductStock(item.id, item.quantity, 'wh1');
    });

    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'SALE_VOID',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Voided Sale ${id}`,
       timestamp: new Date().toISOString(),
       severity: 'high',
       resourceId: id
    });
  };

  const handleStockStatusChange = (type: string, id: string, status: DocumentStatus) => {
    const docMap: any = {
      transfer: 'transfers',
      count: 'counts',
      reservation: 'reservations',
      receipt: 'receipts',
      adjustment: 'adjustments'
    };
    const listName = docMap[type];
    const list = (stockStore as any)[listName] as any[];
    const doc = list.find(x => x.id === id);
    if (doc) {
      stockStore.updateDocument(listName, { ...doc, status });

      if (status === 'Completed' || status === 'Approved') {
         doc.items.forEach((item: any) => {
            const delta = type === 'adjustment' ? item.quantity : type === 'receipt' ? item.quantity : type === 'count' ? (item.countedQuantity - (item.systemQuantity || 0)) : 0;
            if (type === 'transfer') {
               inventoryStore.updateProductStock(item.productId, -item.quantity, doc.sourceWarehouseId);
               inventoryStore.updateProductStock(item.productId, item.quantity, doc.targetWarehouseId);
            } else if (delta !== 0) {
               inventoryStore.updateProductStock(item.productId, delta, doc.warehouseId);
            }
         });
      }
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string, posId?: string) => {
    const newShift: Shift = {
      id: `SHT-${Date.now()}`,
      userId: systemStore.currentUser?.id || 'anon',
      branchId,
      posId,
      startTime: new Date().toISOString(),
      startCash,
      status: 'Open',
      userName: systemStore.currentUser?.name,
      cashTransactions: []
    };
    salesStore.addShift(newShift);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    const shift = salesStore.shifts.find(s => s.id === shiftId);
    if (shift) {
      salesStore.updateShift({
        ...shift,
        endCash,
        notes: notes || shift.notes,
        endTime: new Date().toISOString(),
        status: 'Closed'
      });
    }
  };

  const addCashTransaction = (type: 'in' | 'out', amount: number, reason: string) => {
     const activeShift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
     if (activeShift) {
        const txn: CashTransaction = {
           id: `TXN-${Date.now()}`,
           shiftId: activeShift.id,
           userId: activeShift.userId,
           type,
           amount,
           reason,
           timestamp: new Date().toISOString()
        };
        salesStore.addCashTransaction(activeShift.id, txn);
     }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     const log: SyncLog = {
        id: `LOG-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: 'Local synchronization simulation completed.',
        durationMs: Math.floor(Math.random() * 500) + 100
     };
     systemStore.addSyncLog(log);
  };

  return (
    <GlobalContext.Provider value={{
      currentUser: systemStore.currentUser,
      setCurrentUser: systemStore.setCurrentUser,
      users: systemStore.users,
      roles: systemStore.roles,
      permissions: systemStore.permissions,
      departments: systemStore.departments,
      settings: systemStore.settings,
      products: inventoryStore.products,
      sales: salesStore.sales,
      customers: salesStore.customers,
      customerLevels: salesStore.customerLevels,
      units: inventoryStore.units,
      categories: inventoryStore.categories,
      branches: systemStore.branches,
      posMachines: systemStore.posMachines,
      warehouses: stockStore.warehouses,
      locations: stockStore.locations,
      shifts: salesStore.shifts,
      shiftSchedules: salesStore.shiftSchedules,
      promotions: salesStore.promotions,
      notifications: systemStore.notifications,
      syncLogs: systemStore.syncLogs,
      auditLogs: systemStore.auditLogs || [],

      transfers: stockStore.transfers,
      counts: stockStore.counts,
      reservations: stockStore.reservations,
      receipts: stockStore.receipts,
      adjustments: stockStore.adjustments,

      processSale,
      processReturn,
      settleSaleDebt,
      handleVoidSale,

      addProduct: inventoryStore.addProduct,
      updateProduct: inventoryStore.updateProduct,
      deleteProduct: inventoryStore.deleteProduct,

      addUnit: inventoryStore.addUnit,
      updateUnit: inventoryStore.updateUnit,
      deleteUnit: inventoryStore.deleteUnit,
      addCategory: inventoryStore.addCategory,
      updateCategory: inventoryStore.updateCategory,
      deleteCategory: inventoryStore.deleteCategory,

      addCustomer: salesStore.addCustomer,
      updateCustomer: salesStore.updateCustomer,
      deleteCustomer: (id) => {}, 
      addCustomerLevel: salesStore.addCustomerLevel,
      updateCustomerLevel: salesStore.updateCustomerLevel,
      deleteCustomerLevel: salesStore.deleteCustomerLevel,

      updateTransfer: (t) => stockStore.updateDocument('transfers', t),
      deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),
      updateCount: (c) => stockStore.updateDocument('counts', c),
      deleteCount: (id) => stockStore.deleteDocument('counts', id),
      updateReservation: (r) => stockStore.updateDocument('reservations', r),
      deleteReservation: (id) => stockStore.deleteDocument('reservations', id),
      updateReceipt: (r) => stockStore.updateDocument('receipts', r),
      deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),
      updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
      deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),
      handleStockStatusChange,

      addBranch: systemStore.addBranch,
      updateBranch: systemStore.updateBranch,
      deleteBranch: systemStore.deleteBranch,
      addPos: systemStore.addPos,
      updatePos: systemStore.updatePos,
      deletePos: systemStore.deletePos,

      addWarehouse: stockStore.addWarehouse,
      updateWarehouse: stockStore.updateWarehouse,
      deleteWarehouse: stockStore.deleteWarehouse,
      addLocation: stockStore.addLocation,
      updateLocation: stockStore.updateLocation,
      deleteLocation: stockStore.deleteLocation,

      addUser: systemStore.addUser,
      updateUser: systemStore.updateUser,
      deleteUser: systemStore.deleteUser,

      addRole: systemStore.addRole,
      updateRole: systemStore.updateRole,
      deleteRole: systemStore.deleteRole,

      addDepartment: systemStore.addDepartment,
      updateDepartment: systemStore.updateDepartment,
      deleteDepartment: systemStore.deleteDepartment,

      startShift,
      endShift,
      addShiftSchedule: salesStore.addShiftSchedule,
      updateShiftSchedule: salesStore.updateShiftSchedule,
      deleteShiftSchedule: salesStore.deleteShiftSchedule,
      addCashTransaction,

      addPromotion: salesStore.addPromotion,
      updatePromotion: salesStore.updatePromotion,
      deletePromotion: salesStore.deletePromotion,

      updateSettings: systemStore.updateSettings,
      handleSyncOperation,
      markNotificationRead: systemStore.markNotificationRead,
      clearAllNotifications: systemStore.clearAllNotifications,
      refreshData,
      restoreSystemData: systemStore.restoreSystemData,
      t,
      formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (!context) throw new Error('useGlobal must be used within a GlobalProvider');
  return context;
};

import React, { useState } from 'react';
import { User, UserRoleDefinition, Department } from '../types';
import { Plus, Users, ShieldCheck, Briefcase } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { UserList } from './user/UserList';
import { UserFormModal } from './user/UserFormModal';
import { RoleTab } from './user/RoleTab';
import { DepartmentTab } from './user/DepartmentTab';

export const UserManagement: React.FC = () => {
  const { 
    users, addUser, updateUser, deleteUser,
    roles, addRole, updateRole, deleteRole,
    departments, addDepartment, updateDepartment, deleteDepartment,
    branches, currentUser, permissions
  } = useGlobal();

  const [activeTab, setActiveTab] = useState<'users' | 'roles' | 'departments'>('users');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | undefined>(undefined);

  const handleOpenModal = (user?: User) => {
    if (user && user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can edit other Administrator accounts.");
      return;
    }
    setEditingUser(user);
    setIsModalOpen(true);
  };

  const handleDeleteUser = (user: User) => {
    if (user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can delete Administrator accounts.");
      return;
    }
    if (confirm(`Are you sure you want to delete ${user.name}?`)) {
      deleteUser(user.id);
    }
  };

  const handleSubmitUser = (formData: any, isEdit: boolean) => {
    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      departmentId: formData.departmentId,
      branchId: formData.branchId
    };

    if (formData.password) {
      userData.password = formData.password;
    }

    if (isEdit && editingUser) {
        const existing = users.find(u => u.id === editingUser.id);
        if (existing && !userData.password) {
            userData.password = existing.password;
        }
        updateUser({ ...userData, id: editingUser.id });
    } else {
        addUser({ ...userData, id: `u-${Date.now()}` });
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">System Staff & Access</h2>
          <p className="text-slate-500">Manage users, custom roles, and organization structure.</p>
        </div>

        {activeTab === 'users' && (
          <button 
            onClick={() => handleOpenModal()}
            className="flex items-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-sm whitespace-nowrap"
          >
            <Plus className="w-5 h-5 mr-2" />
            Add User
          </button>
        )}
      </div>

      {/* Tabs Switcher - Style A Pill */}
      <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
         <button 
          onClick={() => setActiveTab('users')}
          className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'users' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          <Users className="w-4 h-4 mr-2" /> Users
        </button>
        <button 
          onClick={() => setActiveTab('roles')}
          className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'roles' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          <ShieldCheck className="w-4 h-4 mr-2" /> Roles & Permissions
        </button>
        <button 
          onClick={() => setActiveTab('departments')}
          className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'departments' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          <Briefcase className="w-4 h-4 mr-2" /> Departments
        </button>
      </div>

      <div className="flex-1 overflow-hidden flex flex-col">
        {activeTab === 'users' && (
          <UserList 
            users={users} 
            branches={branches} 
            currentUser={currentUser} 
            onEdit={handleOpenModal} 
            onDelete={handleDeleteUser} 
          />
        )}

        {activeTab === 'roles' && (
           <RoleTab 
              roles={roles}
              permissions={permissions}
              onAdd={addRole}
              onUpdate={updateRole}
              onDelete={deleteRole}
           />
        )}

        {activeTab === 'departments' && (
           <DepartmentTab 
              departments={departments}
              onAdd={addDepartment}
              onUpdate={updateDepartment}
              onDelete={deleteDepartment}
           />
        )}
      </div>

      <UserFormModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleSubmitUser}
        initialData={editingUser}
        branches={branches}
        departments={departments}
        roles={roles}
        currentUser={currentUser}
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Branch, UserRoleDefinition, Department } from '../../types';
import { X, UserCircle, Edit2, Lock, Mail, Briefcase, Building2, CheckCircle, AlertTriangle } from 'lucide-react';

interface UserFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (formData: any, isEdit: boolean) => void;
  initialData?: User;
  branches: Branch[];
  departments: Department[];
  roles: UserRoleDefinition[];
  currentUser: User | null;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserFormModal: React.FC<UserFormModalProps> = ({ 
  isOpen, onClose, onSubmit, initialData, branches, departments, roles, currentUser 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    departmentId: '',
    branchId: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({ 
        username: initialData.username,
        name: initialData.name,
        email: initialData.email || '',
        role: initialData.role,
        avatarUrl: initialData.avatarUrl || '',
        password: '',
        departmentId: initialData.departmentId || '',
        branchId: initialData.branchId || ''
      });
    } else {
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: roles[0]?.name || 'Cashier',
        avatarUrl: '',
        departmentId: '',
        branchId: ''
      });
    }
  }, [initialData, isOpen, roles]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.username || !formData.name || !formData.role) return;
    if (!initialData && !formData.password) {
        alert("Password is required for new users.");
        return;
    }
    if (currentUser?.role !== 'Admin' && formData.role === 'Admin') {
       alert("You do not have permission to create Administrator accounts.");
       return;
    }
    onSubmit(formData, !!initialData);
  };

  if (!isOpen) return null;

  const selectedRoleDef = roles.find(r => r.name === formData.role);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col animate-fade-in">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl shrink-0">
          <h3 className="text-xl font-bold text-slate-800">
            {initialData ? 'Edit User' : 'Add New User'}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <form onSubmit={handleSubmit} className="p-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Left Column: Form Fields */}
              <div className="space-y-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2">Profile Avatar</label>
                  <div className="flex items-center space-x-4">
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="relative w-16 h-16 rounded-full border-2 border-dashed border-slate-300 bg-slate-50 flex items-center justify-center cursor-pointer hover:bg-slate-100 hover:border-primary-400 transition-colors overflow-hidden group"
                    >
                      {formData.avatarUrl ? (
                        <>
                          <img src={formData.avatarUrl} alt="Preview" className="w-full h-full object-cover" />
                          <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <Edit2 className="w-4 h-4 text-white" />
                          </div>
                        </>
                      ) : (
                        <UserCircle className="w-8 h-8 text-slate-400" />
                      )}
                    </div>

                    <div className="flex-1">
                       <div className="flex space-x-2">
                          <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className="px-3 py-1.5 bg-white border border-slate-300 rounded-md text-xs font-bold text-slate-700 hover:bg-slate-50"
                          >
                            Upload
                          </button>
                          {formData.avatarUrl && (
                            <button
                              type="button"
                              onClick={handleRemoveImage}
                              className="px-3 py-1.5 bg-white border border-red-200 rounded-md text-xs font-bold text-red-600 hover:bg-red-50"
                            >
                              Remove
                            </button>
                          )}
                       </div>
                       <p className="text-[10px] text-slate-400 mt-1 uppercase font-bold tracking-wider">Max 5MB • JPG, PNG</p>
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*"
                      onChange={handleImageUpload}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Full Name</label>
                  <input
                    required
                    type="text"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                    placeholder="John Doe"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Username</label>
                    <input
                      required
                      type="text"
                      value={formData.username}
                      onChange={e => setFormData({...formData, username: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                      placeholder="username"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">
                      Password {initialData && <span className="text-[9px] lowercase font-normal">(Keep empty to skip)</span>}
                    </label>
                    <input
                      required={!initialData}
                      type="password"
                      value={formData.password}
                      onChange={e => setFormData({...formData, password: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                      placeholder="••••••••"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Email Address</label>
                  <input
                    type="email"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                    placeholder="john@example.com"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Department</label>
                    <select
                      value={formData.departmentId || ''}
                      onChange={e => setFormData({...formData, departmentId: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800 appearance-none"
                    >
                      <option value="">None / Floating</option>
                      {departments.map(d => (
                        <option key={d.id} value={d.id}>{d.name}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Assigned Branch</label>
                    <select
                      value={formData.branchId || ''}
                      onChange={e => setFormData({...formData, branchId: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800 appearance-none"
                    >
                      <option value="">Select Branch</option>
                      {branches.map(b => (
                        <option key={b.id} value={b.id}>{b.name}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              {/* Right Column: Role & Permissions */}
              <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-200 h-fit">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-4">Role Selection</label>

                <div className="space-y-3 mb-6">
                  {roles.map(role => {
                    // Only show Admin if current user is Admin
                    if (role.name === 'Admin' && currentUser?.role !== 'Admin') return null;

                    const isSelected = formData.role === role.name;
                    return (
                      <label key={role.id} className={`flex items-center p-4 rounded-2xl border-2 cursor-pointer transition-all ${isSelected ? 'bg-white border-construction-orange shadow-lg' : 'bg-slate-50 border-transparent hover:bg-white'}`}>
                        <input 
                          type="radio" 
                          name="role" 
                          value={role.name} 
                          checked={isSelected}
                          onChange={e => setFormData({...formData, role: e.target.value})}
