                        />
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center mr-4 shrink-0 transition-colors ${isSelected ? 'bg-slate-900 text-white' : 'bg-slate-200 text-slate-400'}`}>
                           <ShieldCheck className="w-5 h-5" />
                        </div>
                        <div className="flex-1 min-w-0">
