              </button>
              <button
                type="submit"
                className="px-10 py-3.5 bg-slate-900 text-white font-black text-sm uppercase tracking-widest rounded-2xl hover:bg-slate-800 transition-all shadow-xl active:scale-95"
              >
                {initialData ? 'Update Record' : 'Create User'}
              </button>
            </div>
          </form>
        </div>
      </div>
