import React, { useState } from 'react';
import { UserRoleDefinition, Permission } from '../../types';
import { ShieldCheck, Plus, Edit2, Trash2, Info } from 'lucide-react';
import { RoleFormModal } from './RoleFormModal';

interface RoleTabProps {
  roles: UserRoleDefinition[];
  permissions: Permission[];
  onAdd: (role: UserRoleDefinition) => void;
  onUpdate: (role: UserRoleDefinition) => void;
  onDelete: (id: string) => void;
}

export const RoleTab: React.FC<RoleTabProps> = ({ roles, permissions, onAdd, onUpdate, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<UserRoleDefinition | undefined>(undefined);

  const handleOpenModal = (role?: UserRoleDefinition) => {
    setEditingRole(role);
    setIsModalOpen(true);
  };

  const handleSave = (data: Partial<UserRoleDefinition>) => {
    if (editingRole) {
      onUpdate({ ...editingRole, ...data } as UserRoleDefinition);
    } else {
      onAdd({ ...data, id: `role-${Date.now()}` } as UserRoleDefinition);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6">
       <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className="p-2.5 bg-slate-900 text-white rounded-xl">
                <ShieldCheck className="w-5 h-5" />
             </div>
             <div>
                <h3 className="text-xl font-black text-slate-900 tracking-tight">Access Control (RBAC)</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Define custom roles and functional permissions</p>
             </div>
          </div>
          <button 
            onClick={() => handleOpenModal()}
            className="flex items-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-xl shadow-slate-200"
          >
             <Plus className="w-5 h-5 mr-2" /> Add Role
          </button>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-y-auto pr-2 custom-scrollbar">
          {roles.map(role => (
             <div key={role.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-100 hover:border-construction-orange transition-all group flex flex-col h-full relative overflow-hidden shadow-sm hover:shadow-xl">
                <div className="flex justify-between items-start mb-6">
                   <div className={`p-3 rounded-2xl shadow-lg ${role.isSystem ? 'bg-slate-900 text-white' : 'bg-orange-50 text-orange-600'}`}>
                      <ShieldCheck className="w-6 h-6" />
                   </div>
                   <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                      <button onClick={() => handleOpenModal(role)} className="p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-colors">
                         <Edit2 className="w-4 h-4" />
                      </button>
                      {!role.isSystem && (
                        <button onClick={() => confirm('Delete role?') && onDelete(role.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-colors">
                           <Trash2 className="w-4 h-4" />
                        </button>
                      )}
                   </div>
                </div>

                <div className="mb-6">
                   <div className="flex items-center gap-2 mb-1">
                      <h4 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">{role.name}</h4>
                      {role.isSystem && <span className="text-[9px] font-black bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded border border-slate-200">SYSTEM</span>}
                   </div>
                   <p className="text-xs font-medium text-slate-400 line-clamp-2">{role.description || 'Custom access level definition'}</p>
                </div>

                <div className="space-y-1.5 mt-auto border-t border-slate-100 pt-4">
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center">
                      <Info className="w-3 h-3 mr-1" /> {role.permissions.length} Active Permissions
                   </p>
                   <div className="flex flex-wrap gap-1.5">
                      {role.permissions.slice(0, 3).map(pId => {
                        const p = permissions.find(x => x.id === pId);
                        return (
                          <span key={pId} className="text-[9px] font-black bg-slate-50 text-slate-600 border border-slate-100 px-2 py-1 rounded-lg uppercase tracking-wide">
                             {p?.label || pId}
                          </span>
                        );
                      })}
                      {role.permissions.length > 3 && (
                         <span className="text-[9px] font-black bg-slate-100 text-slate-400 px-2 py-1 rounded-lg">
                            +{role.permissions.length - 3} MORE
                         </span>
                      )}
                   </div>
                </div>
             </div>
          ))}
       </div>

       <RoleFormModal 
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          onSubmit={handleSave}
          initialData={editingRole}
          allPermissions={permissions}
       />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserRoleDefinition, Permission } from '../../types';
import { X, Check, ShieldCheck, CheckCircle2 } from 'lucide-react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';

interface RoleFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Partial<UserRoleDefinition>) => void;
  initialData?: UserRoleDefinition;
  allPermissions: Permission[];
}

export const RoleFormModal: React.FC<RoleFormModalProps> = ({ 
  isOpen, onClose, onSubmit, initialData, allPermissions 
}) => {
  const [form, setForm] = useState<Partial<UserRoleDefinition>>({
    name: '', description: '', permissions: []
  });

  useEffect(() => {
    if (initialData) setForm(initialData);
    else setForm({ name: '', description: '', permissions: [] });
  }, [initialData, isOpen]);

  const togglePermission = (id: string) => {
     setForm(prev => {
        const current = prev.permissions || [];
        const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
        return { ...prev, permissions: next };
     });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name) return;
    onSubmit(form);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fade-in">
      <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden border border-white/20">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <div>
            <div className="flex items-center gap-2 mb-1">
               <ShieldCheck className="w-5 h-5 text-slate-400" />
               <h3 className="text-2xl font-black text-slate-900 tracking-tight">
                {initialData ? 'Edit Role' : 'Create Custom Role'}
              </h3>
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-7">User Rights Definition</p>
          </div>
          <button onClick={onClose} className="p-2 bg-white rounded-full text-slate-400 hover:text-slate-600 shadow-sm border border-slate-100">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-10 space-y-8 flex-1 overflow-y-auto">
          <div className="space-y-6">
            <Input 
              label="Role Name"
              required
              value={form.name}
              onChange={e => setForm({...form, name: e.target.value})}
              placeholder="e.g. Inventory Clerk"
              className="text-lg font-black uppercase tracking-tighter"
            />

            <div className="space-y-1.5">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Functional Description</label>
               <textarea
                 value={form.description || ''}
                 onChange={e => setForm({...form, description: e.target.value})}
                 className="w-full bg-slate-50 border-2 border-slate-50 rounded-2xl p-4 transition-all outline-none font-bold text-slate-800 focus:ring-4 focus:ring-orange-100 focus:border-construction-orange focus:bg-white resize-none h-20 placeholder:text-slate-300"
                 placeholder="What can users in this role do?"
               />
            </div>

            <div className="space-y-3">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Permissions Map</label>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {allPermissions.map(p => {
                    const isSelected = form.permissions?.includes(p.id);
                    return (
                      <button
                        key={p.id}
                        type="button"
                        onClick={() => togglePermission(p.id)}
                        className={`flex items-start p-3 rounded-2xl border-2 transition-all text-left ${isSelected ? 'bg-white border-construction-orange shadow-md' : 'bg-slate-50 border-transparent hover:border-slate-100'}`}
                      >
                         <div className={`mt-0.5 w-4 h-4 rounded-md border-2 shrink-0 mr-3 flex items-center justify-center transition-colors ${isSelected ? 'bg-construction-orange border-construction-orange' : 'bg-white border-slate-200'}`}>
                            {isSelected && <Check className="w-3 h-3 text-white" />}
                         </div>
                         <div>
                            <p className={`text-xs font-black uppercase tracking-tight ${isSelected ? 'text-slate-900' : 'text-slate-500'}`}>{p.label}</p>
                            <p className="text-[9px] font-medium text-slate-400 mt-0.5 leading-tight">{p.description}</p>
                         </div>
                      </button>
                    )
                  })}
               </div>
            </div>
          </div>

          <div className="flex items-center justify-end space-x-4 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              className="px-8 py-3 text-sm font-black text-slate-400 uppercase tracking-widest hover:text-slate-600 transition-colors"
            >
              Discard
            </button>
            <Button
              type="submit"
              variant="primary"
              size="lg"
              className="min-w-[200px] rounded-2xl"
            >
              <CheckCircle2 className="w-5 h-5 mr-2" />
              Save Access Role
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

