import React, { useState, useEffect, useRef } from 'react';
import { User, Branch, UserRoleDefinition, Department } from '../../types';
// Fix: Added ShieldCheck to the lucide-react imports
import { X, UserCircle, Edit2, Lock, Mail, Briefcase, Building2, CheckCircle, AlertTriangle, ShieldCheck } from 'lucide-react';

interface UserFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (formData: any, isEdit: boolean) => void;
  initialData?: User;
  branches: Branch[];
  departments: Department[];
  roles: UserRoleDefinition[];
  currentUser: User | null;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserFormModal: React.FC<UserFormModalProps> = ({ 
  isOpen, onClose, onSubmit, initialData, branches, departments, roles, currentUser 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    departmentId: '',
    branchId: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({ 
        username: initialData.username,
        name: initialData.name,
        email: initialData.email || '',
        role: initialData.role,
        avatarUrl: initialData.avatarUrl || '',
        password: '',
        departmentId: initialData.departmentId || '',
        branchId: initialData.branchId || ''
      });
    } else {
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: roles[0]?.name || 'Cashier',
        avatarUrl: '',
        departmentId: '',
        branchId: ''
      });
    }
  }, [initialData, isOpen, roles]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.username || !formData.name || !formData.role) return;
    if (!initialData && !formData.password) {
        alert("Password is required for new users.");
        return;
    }
    if (currentUser?.role !== 'Admin' && formData.role === 'Admin') {
       alert("You do not have permission to create Administrator accounts.");
       return;
    }
    onSubmit(formData, !!initialData);
  };

  if (!isOpen) return null;

  const selectedRoleDef = roles.find(r => r.name === formData.role);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col animate-fade-in">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl shrink-0">
          <h3 className="text-xl font-bold text-slate-800">
            {initialData ? 'Edit User' : 'Add New User'}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <form onSubmit={handleSubmit} className="p-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Left Column: Form Fields */}
              <div className="space-y-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2">Profile Avatar</label>
                  <div className="flex items-center space-x-4">
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="relative w-16 h-16 rounded-full border-2 border-dashed border-slate-300 bg-slate-50 flex items-center justify-center cursor-pointer hover:bg-slate-100 hover:border-primary-400 transition-colors overflow-hidden group"
                    >
                      {formData.avatarUrl ? (
                        <>
                          <img src={formData.avatarUrl} alt="Preview" className="w-full h-full object-cover" />
                          <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <Edit2 className="w-4 h-4 text-white" />
                          </div>
                        </>
                      ) : (
                        <UserCircle className="w-8 h-8 text-slate-400" />
                      )}
                    </div>

                    <div className="flex-1">
                       <div className="flex space-x-2">
                          <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className="px-3 py-1.5 bg-white border border-slate-300 rounded-md text-xs font-bold text-slate-700 hover:bg-slate-50"
                          >
                            Upload
                          </button>
                          {formData.avatarUrl && (
                            <button
                              type="button"
                              onClick={handleRemoveImage}
                              className="px-3 py-1.5 bg-white border border-red-200 rounded-md text-xs font-bold text-red-600 hover:bg-red-50"
                            >
                              Remove
                            </button>
                          )}
                       </div>
                       <p className="text-[10px] text-slate-400 mt-1 uppercase font-bold tracking-wider">Max 5MB • JPG, PNG</p>
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*"
                      onChange={handleImageUpload}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Full Name</label>
                  <input
                    required
                    type="text"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                    placeholder="John Doe"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Username</label>
                    <input
                      required
                      type="text"
                      value={formData.username}
                      onChange={e => setFormData({...formData, username: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                      placeholder="username"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">
                      Password {initialData && <span className="text-[9px] lowercase font-normal">(Keep empty to skip)</span>}
                    </label>
                    <input
                      required={!initialData}
                      type="password"
                      value={formData.password}
                      onChange={e => setFormData({...formData, password: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                      placeholder="••••••••"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Email Address</label>
                  <input
                    type="email"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800"
                    placeholder="john@example.com"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Department</label>
                    <select
                      value={formData.departmentId || ''}
                      onChange={e => setFormData({...formData, departmentId: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800 appearance-none"
                    >
                      <option value="">None / Floating</option>
                      {departments.map(d => (
                        <option key={d.id} value={d.id}>{d.name}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">Assigned Branch</label>
                    <select
                      value={formData.branchId || ''}
                      onChange={e => setFormData({...formData, branchId: e.target.value})}
                      className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800 appearance-none"
                    >
                      <option value="">Select Branch</option>
                      {branches.map(b => (
                        <option key={b.id} value={b.id}>{b.name}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              {/* Right Column: Role & Permissions */}
              <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-200 h-fit">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-4">Role Selection</label>

                <div className="space-y-3 mb-6">
                  {roles.map(role => {
                    // Only show Admin if current user is Admin
                    if (role.name === 'Admin' && currentUser?.role !== 'Admin') return null;

                    const isSelected = formData.role === role.name;
                    return (
                      <label key={role.id} className={`flex items-center p-4 rounded-2xl border-2 cursor-pointer transition-all ${isSelected ? 'bg-white border-construction-orange shadow-lg' : 'bg-slate-50 border-transparent hover:bg-white'}`}>
                        <input 
                          type="radio" 
                          name="role" 
                          value={role.name} 
                          checked={isSelected}
                          onChange={e => setFormData({...formData, role: e.target.value})}
                          className="sr-only"
                        />
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center mr-4 shrink-0 transition-colors ${isSelected ? 'bg-slate-900 text-white' : 'bg-slate-200 text-slate-400'}`}>
                           <ShieldCheck className="w-5 h-5" />
                        </div>
                        <div className="flex-1 min-w-0">
                           <span className="block text-sm font-black text-slate-900 uppercase tracking-tight">{role.name}</span>
                           <span className="block text-[10px] text-slate-500 font-bold uppercase tracking-wider">{role.description || 'Custom Access Level'}</span>
                        </div>
                        {isSelected && <CheckCircle className="w-5 h-5 text-construction-orange" />}
                      </label>
                    );
                  })}
                </div>

                <div className="space-y-2 border-t border-slate-200 pt-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Capabilities for {formData.role}</span>
                  <div className="grid grid-cols-1 gap-1">
                    {selectedRoleDef?.permissions.map((pId) => (
                      <div key={pId} className="flex items-center text-xs font-bold text-slate-700 bg-white/50 px-3 py-2 rounded-lg border border-slate-100">
                        <CheckCircle className="w-3.5 h-3.5 text-emerald-500 mr-2 shrink-0" />
                        <span>{roles.find(r => r.name === 'Admin')?.id === 'Admin' ? 'System Superuser' : pId}</span>
                      </div>
                    ))}
                    {(!selectedRoleDef?.permissions || selectedRoleDef.permissions.length === 0) && (
                       <p className="text-[10px] text-slate-400 italic">No specific permissions assigned.</p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex justify-end pt-6 mt-6 border-t border-slate-100 space-x-3">
              <button
                type="button"
                onClick={onClose}
                className="px-8 py-3 text-sm font-black text-slate-400 uppercase tracking-widest hover:text-slate-600 transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-10 py-3.5 bg-slate-900 text-white font-black text-sm uppercase tracking-widest rounded-2xl hover:bg-slate-800 transition-all shadow-xl active:scale-95"
              >
                {initialData ? 'Update Record' : 'Create User'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Hammer, ChevronLeft, ChevronRight } from 'lucide-react';
import { User, UserRole } from '../../types';
import { cn } from '../../lib/utils';

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

interface DesktopSidebarProps {
  navItems: NavItemConfig[];
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  t: (key: string) => string;
  mobileMenuOpen: boolean;
  setMobileMenuOpen: (open: boolean) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const DesktopSidebar: React.FC<DesktopSidebarProps> = ({
  navItems,
  activeTab,
  onTabChange,
  currentUser,
  t,
  mobileMenuOpen,
  setMobileMenuOpen,
  isCollapsed,
  onToggleCollapse
}) => {
  const visibleNavItems = navItems.filter(item => 
    // Fix: Cast currentUser.role to UserRole to satisfy TypeScript array inclusion check
    currentUser && item.allowedRoles.includes(currentUser.role as UserRole)
  );

  return (
    <aside className={cn(
      "fixed inset-y-0 left-0 z-50 bg-slate-900 text-white transition-all duration-500 cubic-bezier(0.4, 0, 0.2, 1) flex flex-col border-r border-white/5 md:relative md:translate-x-0 shadow-2xl shadow-black/50",
      mobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0',
      isCollapsed ? 'md:w-24' : 'md:w-72'
    )}>
      <div className={cn("flex items-center h-24 shrink-0 relative", isCollapsed ? 'justify-center' : 'px-8')}>
        <div className="flex items-center gap-4 overflow-hidden">
          <div className="bg-gradient-to-br from-construction-orange to-orange-600 p-3 rounded-2xl shadow-xl shadow-orange-900/20 shrink-0 border border-white/10">
            <Hammer className="w-6 h-6 text-white" />
          </div>
          {!isCollapsed && (
             <div className="animate-fade-in">
                <h1 className="text-xl font-black tracking-tight text-white leading-none">BuildMaster</h1>
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] mt-1.5">AI Construction POS</p>
             </div>
          )}
        </div>

        <button 
          onClick={onToggleCollapse}
          className="hidden md:flex absolute -right-3 top-9 bg-slate-800 text-slate-400 hover:text-white border border-slate-700 rounded-full w-7 h-7 items-center justify-center shadow-2xl transition-all z-50 hover:scale-110"
        >
           {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
        </button>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 py-4 space-y-1.5">
        {visibleNavItems.map(item => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => {
                onTabChange(item.id);
                setMobileMenuOpen(false);
              }}
              className={cn(
                "flex items-center w-full px-4 py-4 rounded-2xl transition-all duration-300 group relative",
                isActive 
                  ? 'bg-construction-orange text-white shadow-lg shadow-orange-900/20 font-bold' 
                  : 'text-slate-500 hover:bg-white/5 hover:text-slate-200',
                isCollapsed && 'justify-center'
              )}
            >
              <Icon className={cn("w-6 h-6 shrink-0 transition-transform", isActive ? 'scale-110' : 'group-hover:scale-110', !isCollapsed && 'mr-4')} />
              {!isCollapsed && (
                 <span className="flex-1 text-left truncate text-xs font-black uppercase tracking-wider">{t(`nav.${item.id}`)}</span>
              )}

              {isCollapsed && (
                 <div className="absolute left-full ml-4 px-3 py-2 bg-slate-800 text-white text-[10px] font-black uppercase tracking-widest rounded-xl opacity-0 group-hover:opacity-100 pointer-events-none transition-all duration-300 whitespace-nowrap z-50 border border-slate-700 shadow-2xl translate-x-2 group-hover:translate-x-0">
                    {t(`nav.${item.id}`)}
                 </div>
              )}
            </button>
          );
        })}
      </div>

      <div className={cn("p-6", isCollapsed && "p-2")}>
         <div className="bg-white/5 rounded-3xl p-4 text-center border border-white/5 backdrop-blur-sm">
            {!isCollapsed && <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Version 1.0.4</p>}
            <p className="text-[9px] text-construction-orange font-black mt-1">OFFLINE MODE</p>
         </div>
      </div>
    </aside>
  );
};
